import {PRESETS,PianoEngine,frequency,attackSeconds,releaseSeconds} from './audio.js';
const $=selector=>document.querySelector(selector),engine=new PianoEngine();
const state={preset:'grand',octave:4,octaves:innerWidth<740?1:2,pedal:false,spacePedal:false};
const pressed=new Map(),computer=new Map();let generation=0,ready=false;
const notes=['Do','Do♯','Re','Re♯','Mi','Fa','Fa♯','Sol','Sol♯','La','La♯','Si'];
const shortcuts=['KeyA','KeyW','KeyS','KeyE','KeyD','KeyF','KeyT','KeyG','KeyY','KeyH','KeyU','KeyJ','KeyK','KeyO','KeyL','KeyP','Semicolon'];
const labels=['A','W','S','E','D','F','T','G','Y','H','U','J','K','O','L','P',';'];
$('#presets').innerHTML=PRESETS.map((p,i)=>`<button class="preset" data-preset="${p.id}" aria-pressed="${i===0}"><span class="preset-number">0${i+1}</span><span class="preset-name">${p.name}</span><span class="preset-light" aria-hidden="true"></span></button>`).join('');
function control(id,label){return `<label class="knob-control" for="${id}"><span class="knob-label">${label}</span><span class="knob-face" aria-hidden="true"></span><output id="${id}-value" for="${id}"></output><input id="${id}" type="range" min="0" max="100" value="0"></label>`;}
$('#tone-controls').innerHTML=control('cutoff','Freqüència')+control('resonance','Ressonància');
$('#effect-controls').innerHTML=control('reverb','Reverberació')+control('delay','Eco');
$('#envelope-controls').innerHTML=control('attack','Atac')+control('release','Durada en deixar anar');
for(const face of document.querySelectorAll('.knob-face')){let drag;face.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();const range=face.parentElement.querySelector('input');if(range.disabled)return;drag={id:e.pointerId,y:e.clientY,value:Number(range.value),range};face.setPointerCapture(e.pointerId);});face.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;e.preventDefault();drag.range.value=Math.max(0,Math.min(100,Math.round(drag.value+(drag.y-e.clientY)*.7)));drag.range.dispatchEvent(new Event('input',{bubbles:true}));});for(const event of ['pointerup','pointercancel','lostpointercapture'])face.addEventListener(event,()=>{drag=null;});}
const formatNumber=(v,d=1)=>v.toLocaleString('ca',{maximumFractionDigits:d});
function syncParameters(){for(const id of ['cutoff','resonance','reverb','delay','attack','release']){const value=engine.settings[id],range=$('#'+id);range.value=value;const angle=value*2.7;range.parentElement.style.setProperty('--fill',`${angle}deg`);range.parentElement.style.setProperty('--rotation',`${angle-135}deg`);let label=value+'%';if(id==='cutoff'){const hz=frequency(value);label=hz>=1000?formatNumber(hz/1000)+' kHz':Math.round(hz)+' Hz';}if(id==='attack')label=Math.round(attackSeconds(value)*1000)+' ms';if(id==='release')label=formatNumber(releaseSeconds(value),2)+' s';$('#'+id+'-value').textContent=label;range.setAttribute('aria-valuetext',label);}$('#filter-type').value=engine.settings.filter;const disabled=engine.settings.filter==='off';$('#cutoff').disabled=disabled;$('#resonance').disabled=disabled;}
function updatePedal(){const on=state.pedal||state.spacePedal;engine.setSustain(on);$('#sustain').setAttribute('aria-pressed',String(on));}
function silence(){generation++;pressed.clear();computer.clear();engine.panic();state.pedal=false;state.spacePedal=false;updatePedal();paintKeys();}
function selectPreset(id){silence();engine.setPreset(id);state.preset=id;const p=engine.preset;$('#sound-name').textContent=p.name;$('#sound-family').textContent=p.family;$('#sound-description').textContent=p.description;$('#sound-count').textContent=`0${PRESETS.indexOf(p)+1} / 06`;document.querySelectorAll('.preset').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset===id)));syncParameters();}
function renderKeyboard(){silence();$('#keyboard-size').value=state.octaves;$('#octave').textContent=state.octave;$('#octave-down').disabled=state.octave<=2;$('#octave-up').disabled=state.octave>=6;const keyboard=$('#keyboard');keyboard.replaceChildren();let white=0;const width=100/(state.octaves*7+1);for(let i=0;i<=state.octaves*12;i++){const midi=(state.octave+1)*12+i,black=[1,3,6,8,10].includes(i%12),b=document.createElement('button');b.className=`key ${black?'black':'white'} ${i%12===0?'root':''}`;b.style.width=`${width*(black?.62:1)}%`;b.style.left=`${(black?white-.31:white)*width}%`;b.dataset.midi=midi;b.setAttribute('aria-label',`${notes[i%12]} ${Math.floor(midi/12)-1}`);b.setAttribute('aria-pressed','false');b.innerHTML=`<span class="note-name">${black?'':notes[i%12]+(i%12===0?' '+(Math.floor(midi/12)-1):'')}</span><span class="key-shortcut">${labels[i]||'·'}</span>`;b.addEventListener('click',e=>{if(e.detail===0){const id='access-'+midi;begin(id,midi,.8);setTimeout(()=>end(id),280);}});keyboard.append(b);if(!black)white++;}}
function paintKeys(){const active=new Set([...pressed.values()].map(x=>x.midi));document.querySelectorAll('.key').forEach(b=>{const on=active.has(Number(b.dataset.midi));b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});}
engine.onchange=()=>{$('#voices').textContent=engine.voices.size+' '+(engine.voices.size===1?'veu':'veus');};
engine.onstatus=text=>{$('#audio-status').textContent=text;};
async function unlock(){try{if(!ready)$('#power-label').textContent='Preparant…';const running=await engine.start();if(!running)return false;ready=true;$('#power').classList.add('active');$('#power-label').textContent='So activat';if(engine.context){engine.context.onstatechange=()=>{if(engine.context.state!=='running'){$('#power').classList.remove('active');$('#power-label').textContent='Reactiva el so';ready=false;silence();}};}return true;}catch(error){$('#audio-status').textContent=error.message||'No s’ha pogut activar el so. Torna-ho a provar.';$('#power-label').textContent='Torna-ho a provar';return false;}}
function begin(id,midi,velocity){end(id);const token={midi,generation};pressed.set(id,token);paintKeys();if(ready&&engine.context?.state==='running'){engine.noteOn(id,midi,velocity);return;}unlock().then(ok=>{if(ok&&pressed.get(id)===token&&token.generation===generation)engine.noteOn(id,midi,velocity);});}
function end(id){pressed.delete(id);engine.noteOff(id);paintKeys();}
function keyAt(x,y){const el=document.elementFromPoint(x,y)?.closest('.key');return el&&$('#keyboard').contains(el)?el:null;}
const keyboard=$('#keyboard');
keyboard.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const key=keyAt(e.clientX,e.clientY);if(!key)return;e.preventDefault();keyboard.setPointerCapture(e.pointerId);const rect=key.getBoundingClientRect();begin('pointer-'+e.pointerId,Number(key.dataset.midi),Math.max(.4,Math.min(1,.4+.6*(e.clientY-rect.top)/rect.height)));});
keyboard.addEventListener('pointermove',e=>{if(!keyboard.hasPointerCapture(e.pointerId))return;e.preventDefault();const id='pointer-'+e.pointerId,key=keyAt(e.clientX,e.clientY),current=pressed.get(id);if(!key){if(current)end(id);return;}const midi=Number(key.dataset.midi);if(current?.midi!==midi)begin(id,midi,.78);});
for(const event of ['pointerup','pointercancel','lostpointercapture'])keyboard.addEventListener(event,e=>end('pointer-'+e.pointerId));
keyboard.addEventListener('contextmenu',e=>e.preventDefault());
const editable=target=>target instanceof Element&&!!target.closest('input,select,textarea,[contenteditable="true"],dialog[open]');
document.addEventListener('keydown',e=>{if(e.code==='Escape'){silence();return;}if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||editable(e.target)||$('#help').open)return;if(e.code==='Space'){if(e.target instanceof Element&&e.target.closest('button,summary,a'))return;e.preventDefault();state.spacePedal=true;updatePedal();return;}const offset=shortcuts.indexOf(e.code);if(offset<0||offset>state.octaves*12)return;e.preventDefault();const id='key-'+e.code;computer.set(e.code,id);begin(id,(state.octave+1)*12+offset,.8);});
document.addEventListener('keyup',e=>{if(e.code==='Space'){state.spacePedal=false;updatePedal();}const id=computer.get(e.code);if(id){end(id);computer.delete(e.code);}});
window.addEventListener('blur',silence);document.addEventListener('visibilitychange',()=>{if(document.hidden)silence();});window.addEventListener('pagehide',silence);
$('#power').addEventListener('click',()=>{unlock();$('#power').blur();});
$('#presets').addEventListener('click',e=>{const b=e.target.closest('[data-preset]');if(b){selectPreset(b.dataset.preset);b.blur();}});
for(const id of ['cutoff','resonance','reverb','delay','attack','release'])$('#'+id).addEventListener('input',e=>{engine.setParameter(id,Number(e.target.value));syncParameters();});
$('#filter-type').addEventListener('change',e=>{engine.setParameter('filter',e.target.value);syncParameters();});
$('#volume').addEventListener('input',e=>{engine.setVolume(Number(e.target.value)/100);$('#volume-value').textContent=e.target.value+'%';});
$('#reset').addEventListener('click',()=>selectPreset(state.preset));
$('#sustain').addEventListener('click',()=>{state.pedal=!state.pedal;updatePedal();$('#sustain').blur();});
$('#panic').addEventListener('click',silence);
$('#octave-down').addEventListener('click',()=>{state.octave=Math.max(2,state.octave-1);renderKeyboard();});
$('#octave-up').addEventListener('click',()=>{state.octave=Math.min(6,state.octave+1);renderKeyboard();});
$('#keyboard-size').addEventListener('change',e=>{state.octaves=Number(e.target.value);renderKeyboard();});
const narrow=matchMedia('(max-width:740px)');narrow.addEventListener('change',e=>{state.octaves=e.matches?1:2;renderKeyboard();});
function openHelp(){silence();$('#help').showModal();}
$('#help-button').addEventListener('click',openHelp);$('#credits-button').addEventListener('click',openHelp);$('#close-help').addEventListener('click',()=>$('#help').close());$('#help').addEventListener('click',e=>{if(e.target===$('#help')){const r=$('#help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#help').close();}});
if(!document.fullscreenEnabled)$('#fullscreen').classList.add('hidden');
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('#audio-status').textContent='La pantalla completa no està disponible aquí.';}});
document.addEventListener('fullscreenchange',()=>{$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'Surt de pantalla completa':'Pantalla completa');});
syncParameters();renderKeyboard();
const canvas=$('#scope'),ctx=canvas.getContext('2d'),wave=new Uint8Array(1024);let lastFrame=0;
function draw(time){requestAnimationFrame(draw);if(document.hidden||time-lastFrame<42)return;lastFrame=time;const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#263646';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<w;x+=40){ctx.moveTo(x,0);ctx.lineTo(x,h);}for(let y=15;y<h;y+=20){ctx.moveTo(0,y);ctx.lineTo(w,y);}ctx.stroke();ctx.strokeStyle='#9ab9e8';ctx.lineWidth=2;ctx.beginPath();if(engine.analyser)engine.analyser.getByteTimeDomainData(wave);else wave.fill(128);for(let i=0;i<wave.length;i++){const x=i/wave.length*w,y=h/2+(wave[i]-128)/128*h*.85;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();}
requestAnimationFrame(draw);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const result=()=>({sound:state.preset,settings:{...engine.settings},octave:state.octave,volume:engine.volume});const tools=[{name:'read_piano_settings',title:'Consulta el piano',description:'Read the selected sound, filter and effect settings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>result()},{name:'configure_piano',title:'Ajusta el piano',description:'Select a sound or adjust filters and effects. Does not start playback.',inputSchema:{type:'object',properties:{sound:{type:'string',enum:PRESETS.map(p=>p.id)},filter:{type:'string',enum:['lowpass','highpass','bandpass','off']},...Object.fromEntries(['cutoff','resonance','reverb','delay','attack','release'].map(n=>[n,{type:'number',minimum:0,maximum:100}]))},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Cal un objecte');for(const [k,v]of Object.entries(input)){if(k==='sound'){if(!PRESETS.some(p=>p.id===v))throw new Error('So desconegut');}else if(k==='filter'){if(!['lowpass','highpass','bandpass','off'].includes(v))throw new Error('Filtre no vàlid');}else if(!['cutoff','resonance','reverb','delay','attack','release'].includes(k)||!Number.isFinite(v)||v<0||v>100)throw new Error('Paràmetre no vàlid');}if(input.sound)selectPreset(input.sound);for(const [k,v]of Object.entries(input))if(k!=='sound')engine.setParameter(k,v);syncParameters();return result();}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
